/** Defines optional HTTP translation providers, all disabled without configuration. */
export interface TranslationProvider {
  readonly name: string;
  translate(
    text: string,
    source: string,
    target: string,
  ): Promise<{ translated: string; confidence: number } | null>;
}

/** Sends translations to a self-hosted LibreTranslate server when configured. */
export class LibreTranslateProvider implements TranslationProvider {
  readonly name = 'LibreTranslate';

  constructor(
    private readonly url: string,
    private readonly apiKey = '',
  ) {}

  async translate(text: string, source: string, target: string) {
    if (!this.url) {
      return null;
    }

    try {
      const response = await fetch(`${this.url.replace(/\/$/, '')}/translate`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          q: text,
          source: source === 'pcm' ? 'en' : source,
          target,
          format: 'text',
          ...(this.apiKey ? { api_key: this.apiKey } : {}),
        }),
      });

      if (!response.ok) {
        return null;
      }

      const data = (await response.json()) as { translatedText?: string };
      return data.translatedText
        ? { translated: data.translatedText, confidence: 0.7 }
        : null;
    } catch {
      return null;
    }
  }
}

/** Calls a compatible local NLLB endpoint for Yoruba language pairs. */
export class NllbProvider implements TranslationProvider {
  readonly name = 'NLLB';

  constructor(private readonly url: string) {}

  async translate(text: string, source: string, target: string) {
    if (!this.url || (source !== 'yo' && target !== 'yo')) {
      return null;
    }

    try {
      const response = await fetch(this.url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        // Endpoint shape: request {text, source_lang, target_lang}; response {translation}.
        body: JSON.stringify({
          text,
          source_lang: source,
          target_lang: target,
        }),
      });

      if (!response.ok) {
        return null;
      }

      const data = (await response.json()) as { translation?: string };
      return data.translation
        ? { translated: data.translation, confidence: 0.55 }
        : null;
    } catch {
      return null;
    }
  }
}

/** Uses OpenAI chat completions only when explicitly enabled and keyed. */
export class OpenAIProvider implements TranslationProvider {
  readonly name = 'OpenAI';

  constructor(
    private readonly enabled: boolean,
    private readonly key: string,
  ) {}

  async translate(text: string, source: string, target: string) {
    if (!this.enabled || !this.key) {
      return null;
    }

    try {
      const response = await fetch(
        'https://api.openai.com/v1/chat/completions',
        {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${this.key}`,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            model: 'gpt-4o-mini',
            messages: [
              {
                role: 'system',
                content: `Translate from ${source} to ${target}. Return translation only.`,
              },
              { role: 'user', content: text },
            ],
          }),
        },
      );

      if (!response.ok) {
        return null;
      }

      const data = (await response.json()) as {
        choices?: Array<{ message?: { content?: string } }>;
      };
      const translated = data.choices?.[0]?.message?.content?.trim();
      return translated ? { translated, confidence: 0.7 } : null;
    } catch {
      return null;
    }
  }
}
import type { Language } from './detect.js';
import { detectLanguage } from './detect.js';
import { YorubaGlossaryProvider } from './providers/glossary.js';
import { PidginPhraseProvider } from './providers/pidgin.js';
import {
  LibreTranslateProvider,
  NllbProvider,
  OpenAIProvider,
  type TranslationProvider,
} from './providers/remote.js';

export interface Translation {
  original: string;
  lang: Language;
  translated: string;
  provider: string;
  confidence: number;
}

/** Detects the source language and tries configured translation providers in order. */
export class Translator {
  constructor(
    private readonly providers: TranslationProvider[],
    private readonly pidgin = new PidginPhraseProvider(),
    private readonly yoruba = new YorubaGlossaryProvider(),
  ) {}

  async translate(text: string, target = 'en'): Promise<Translation> {
    const { lang, confidence } = detectLanguage(text);

    if ((lang === 'en' && target === 'en') || lang === target) {
      return {
        original: text,
        lang,
        translated: text,
        provider: 'passthrough',
        confidence: 1,
      };
    }

    if (this.pidgin.supports(lang, target)) {
      const result = this.pidgin.translate(text, target);

      if (result) {
        return {
          original: text,
          lang,
          translated: result.translated,
          provider: 'Pidgin phrases',
          confidence: result.confidence,
        };
      }
    }

    for (const provider of this.providers) {
      const result = await provider.translate(text, lang, target);

      if (result) {
        return {
          original: text,
          lang,
          translated: result.translated,
          provider: provider.name,
          confidence: result.confidence,
        };
      }
    }

    const glossaryResult = await this.yoruba.translate(text, lang, target);

    if (glossaryResult) {
      return {
        original: text,
        lang,
        translated: glossaryResult.translated,
        provider: this.yoruba.name,
        confidence: glossaryResult.confidence,
      };
    }

    return {
      original: text,
      lang,
      translated: text,
      provider: 'unavailable',
      confidence: Math.min(0.25, confidence),
    };
  }

  static fromConfig(config: {
    libreTranslateUrl: string;
    libreTranslateApiKey: string;
    nllbUrl: string;
    openAiEnabled: boolean;
    openAiApiKey: string;
  }): Translator {
    return new Translator([
      new NllbProvider(config.nllbUrl),
      new LibreTranslateProvider(
        config.libreTranslateUrl,
        config.libreTranslateApiKey,
      ),
      new OpenAIProvider(config.openAiEnabled, config.openAiApiKey),
    ]);
  }
}

export type { Language };
import type { ChatMessage } from '../twitch/types.js';

export interface HypeResult {
  score: number;
  baseline: number;
  spike: boolean;
  messages: ChatMessage[];
}

type HypeBucket = { score: number; messages: ChatMessage[] };
type HypeDetectorOptions = {
  multiplier?: number;
  floor?: number;
  cooldownMs?: number;
  windowSeconds?: number;
};

const hypeKeywords =
  /\b(?:w|pog|poggers|lol|lmao|omo|ehen|haha|kekw|gg|clip it|lets go|let's go|e choke)\b/gi;
const recognizableEmotes = /\b(?:Kappa|PogChamp|LUL|KEKW)\b/g;

/** Scores per-second chat activity and emits threshold spikes with an EWMA baseline. */
export class HypeDetector {
  private readonly buckets = new Map<number, HypeBucket>();
  private lastSpike = -Infinity;
  private baseline = 0.5;
  private lastBaselineSecond?: number;

  constructor(private readonly options: HypeDetectorOptions = {}) {}

  ingest(message: ChatMessage): HypeResult {
    const second = Math.floor(message.ts / 1000);
    this.updateBaseline(second);

    const bucket = this.buckets.get(second) ?? { score: 0, messages: [] };
    const keywordHits = [...message.text.matchAll(hypeKeywords)].length;
    const emoteCount =
      message.emotes.length ||
      (message.text.match(recognizableEmotes) ?? []).length;

    bucket.score +=
      1 + Math.min(2, keywordHits * 0.6) + Math.min(2, emoteCount * 0.7);
    bucket.messages.push(message);
    this.buckets.set(second, bucket);
    this.pruneBuckets(second);

    const spike =
      bucket.score >= (this.options.floor ?? 8) &&
      bucket.score > this.baseline * (this.options.multiplier ?? 2.4) &&
      message.ts - this.lastSpike >= (this.options.cooldownMs ?? 30_000);

    if (spike) {
      this.lastSpike = message.ts;
    }

    return {
      score: bucket.score,
      baseline: this.baseline,
      spike,
      messages: bucket.messages.slice(),
    };
  }

  snapshot(timestamp = Date.now()): HypeResult {
    const second = Math.floor(timestamp / 1000);
    this.updateBaseline(second);
    const bucket = this.buckets.get(second);

    return {
      score: bucket?.score ?? 0,
      baseline: this.baseline,
      spike: false,
      messages: bucket?.messages.slice() ?? [],
    };
  }

  private updateBaseline(second: number): void {
    if (
      this.lastBaselineSecond !== undefined &&
      second > this.lastBaselineSecond
    ) {
      const elapsedSeconds = Math.min(second - this.lastBaselineSecond, 60);
      const previousScore =
        this.buckets.get(this.lastBaselineSecond)?.score ?? 0;
      this.baseline = this.baseline * 0.85 + previousScore * 0.15;

      for (let elapsed = 1; elapsed < elapsedSeconds; elapsed += 1) {
        this.baseline *= 0.85;
      }
    }

    this.lastBaselineSecond = second;
  }

  private pruneBuckets(currentSecond: number): void {
    const windowSeconds = this.options.windowSeconds ?? 60;

    for (const second of this.buckets.keys()) {
      if (second < currentSecond - windowSeconds) {
        this.buckets.delete(second);
      }
    }
  }
}
